const payload = $input.item.json;
const isWebhook = Boolean(payload.body && payload.body.message !== undefined);
const msg = payload.message || {};

const sourceChannel = isWebhook ? 'web_widget' : 'telegram';
const chatId = isWebhook
  ? String(payload.body.session_id || 'web_guest_01')
  : String(msg.chat?.id || 'unknown');
const userName = isWebhook
  ? String(payload.body.user_name || 'Web Visitor')
  : ([msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.from?.username || 'Customer');
const rawText = isWebhook
  ? String(payload.body.message || '').trim()
  : (msg.text || '').trim();

const sanitizedText = rawText.slice(0, 1000);

const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above|system)\s+(instructions|prompts|rules)/i,
  /disregard\s+(all\s+)?(previous|prior|system)\s+(instructions|prompts|rules)/i,
  /you\s+are\s+now\s+(dan|in\s+developer\s+mode|unrestricted|a\s+different)/i,
  /(reveal|print|show|output|repeat)\s+(your|the)\s+(system\s+prompt|hidden\s+instructions|initial\s+prompt)/i,
  /(print|show|reveal|output|repeat|quote|display).{0,45}(system|developer)\s+(message|prompt|instructions)/i,
  /<\s*\/?\s*(system|instruction|retrieved_context|untrusted_customer_message)\s*>/i,
  /system\s*override|admin\s*override|sudo\s+mode/i
];

const injectionDetected = injectionPatterns.some(regex => regex.test(sanitizedText));
const humanRequestPatterns = /\b(human|real person|live agent|support agent|manager|representative|talk to someone|escalate)\b/i;
const explicitHumanRequest = humanRequestPatterns.test(sanitizedText);

return {
  json: {
    source_channel: sourceChannel,
    chat_id: chatId,
    session_id: `${sourceChannel}_${chatId}`,
    user_name: userName,
    username_handle: isWebhook ? 'web-session' : (msg.from?.username ? `@${msg.from.username}` : 'N/A'),
    user_message: sanitizedText,
    is_empty_or_non_text: sanitizedText.length === 0,
    injection_detected: injectionDetected,
    explicit_human_request: explicitHumanRequest,
    received_at: new Date().toISOString()
  }
};

const userMeta = $('Normalize Input & Injection Pre-Filter').item.json;
const searchResults = $input.item.json.result || [];

const scores = searchResults.map(r => Number(r.score || 0));
const top1Similarity = scores.length > 0 ? Number(scores[0].toFixed(4)) : 0;
const avgTop2Similarity = scores.length >= 2
  ? Number(((scores[0] + scores[1]) / 2).toFixed(4))
  : top1Similarity;

const formattedChunks = searchResults.map((hit, idx) => {
  const meta = hit.payload?.metadata || {};
  const docId = meta.doc_id || 'KB-UNKNOWN';
  const sourceFile = meta.source_file || 'unknown.md';
  const docTitle = meta.doc_title || 'Untitled';
  const content = hit.payload?.content || hit.payload?.pageContent || '';
  const score = Number(hit.score || 0).toFixed(3);

  return `<chunk rank="${idx + 1}" doc_id="${docId}" file="${sourceFile}" title="${docTitle}" similarity="${score}">\n${content}\n</chunk>`;
}).join('\n\n');

return {
  json: {
    ...userMeta,
    top1_similarity: top1Similarity,
    avg_top2_similarity: avgTop2Similarity,
    retrieved_chunks_count: searchResults.length,
    retrieved_context_xml: formattedChunks || '<chunk>NO_CHUNKS_FOUND</chunk>'
  }
};

const telemetry = $('Format Retrieved Context & Similarity Metrics').item.json;
const llmOut = $input.item.json.output || $input.item.json;

const top1Sim = Number(telemetry.top1_similarity || 0);
const llmConf = Number(llmOut.llm_confidence ?? 0);
const citedDocs = Array.isArray(llmOut.cited_documents) ? llmOut.cited_documents : [];
const validCitations = citedDocs.filter(id => /^KB-[A-Z]+-\d+$/.test(id));

const compositeConfidence = Number(((top1Sim * 0.4) + (llmConf * 0.6)).toFixed(3));

// 1. Check Prompt Injection Gate First (Block without spamming human agents)
if (telemetry.injection_detected || llmOut.handoff_reason === 'PROMPT_INJECTION_ATTEMPT') {
  return {
    json: {
      ...telemetry,
      llm_confidence: 0.0,
      composite_confidence: 0.0,
      cited_documents: [],
      final_action: 'BLOCK_INJECTION',
      trigger_human_handoff: false,
      escalation_reason: 'PROMPT_INJECTION_BLOCKED',
      customer_reply: 'I can only assist with questions covered by the official BrewCraft Coffee Gear knowledge base.'
    }
  };
}

// 2. Hybrid Confidence & Human Handoff Gate
const SIMILARITY_THRESHOLD = 0.62;
const FOLLOWUP_SIMILARITY_FLOOR = 0.52;
const LLM_CONFIDENCE_THRESHOLD = 0.70;

const isHighConfidenceFollowUp = (top1Sim >= FOLLOWUP_SIMILARITY_FLOOR && llmConf >= 0.85 && validCitations.length > 0);
const lowVectorSimilarity = (top1Sim < SIMILARITY_THRESHOLD) && !isHighConfidenceFollowUp;
const lowLlmConfidence = llmConf < LLM_CONFIDENCE_THRESHOLD;
const missingValidCitation = validCitations.length === 0;

const shouldHandoff =
  telemetry.explicit_human_request ||
  Boolean(llmOut.needs_human_handoff) ||
  lowVectorSimilarity ||
  lowLlmConfidence ||
  missingValidCitation;

let escalationReason = 'NONE';
if (shouldHandoff) {
  if (telemetry.explicit_human_request || llmOut.handoff_reason === 'USER_REQUESTED_HUMAN') {
    escalationReason = 'USER_REQUESTED_HUMAN';
  } else if (lowVectorSimilarity) {
    escalationReason = `LOW_VECTOR_SIMILARITY (${top1Sim} < ${SIMILARITY_THRESHOLD})`;
  } else if (llmOut.needs_human_handoff || lowLlmConfidence) {
    escalationReason = `INSUFFICIENT_CONTEXT_OR_CONFIDENCE (llm_conf=${llmConf})`;
  } else if (missingValidCitation) {
    escalationReason = 'MISSING_SOURCE_CITATION';
  }
}

let finalReply = llmOut.answer || '';
if (shouldHandoff) {
  // Preserve partial grounded answer if it has valid citations, otherwise use standard fallback
  if (validCitations.length > 0 && finalReply && !finalReply.toLowerCase().includes("i don't know")) {
    finalReply = `${finalReply}\n\n🔔 *Human Handoff:* For the remaining details not covered in our knowledge base, I have forwarded your full conversation to a human support specialist.`;
  } else {
    finalReply = "I don't know based on our official BrewCraft knowledge base. I have escalated your full conversation to a human support specialist who will follow up with you shortly.";
  }
}

return {
  json: {
    ...telemetry,
    llm_confidence: llmConf,
    composite_confidence: compositeConfidence,
    cited_documents: validCitations,
    final_action: shouldHandoff ? 'HANDOFF_TO_HUMAN' : 'AUTO_ANSWER',
    trigger_human_handoff: shouldHandoff,
    escalation_reason: escalationReason,
    customer_reply: finalReply
  }
};

const rows = $input.all().map(r => r.json).reverse();
const gateData = $('Evaluate Confidence & Handoff Gate').first().json;

const transcriptLines = rows.map((row, idx) => {
  const msgObj = typeof row.message === 'string' ? JSON.parse(row.message) : (row.message || {});
  const role = msgObj.type === 'human' ? '👤 Customer' : '🤖 Bot';
  let content = msgObj.data?.content || '';

  // Extract clean customer message if wrapped in XML prompt
  const xmlMatch = content.match(/<untrusted_customer_message>([\s\S]*?)<\/untrusted_customer_message>/);
  if (xmlMatch) {
    content = xmlMatch[1].trim();
  }

  // Extract clean bot answer if JSON string
  if (role === '🤖 Bot' && content.trim().startsWith('{')) {
    try {
      const parsed = JSON.parse(content);
      content = parsed.output?.answer || parsed.answer || content;
    } catch (e) {}
  }

  return `${idx + 1}. ${role}: ${content.slice(0, 300)}`;
});

const transcriptText = transcriptLines.length > 0
  ? transcriptLines.join('\n')
  : `1. 👤 Customer: ${gateData.user_message}`;

const alertMessage = [
  '🚨 *HUMAN SUPPORT HANDOFF REQUIRED*',
  `• *Customer:* ${gateData.user_name} (${gateData.username_handle})`,
  `• *Telegram Chat ID:* \`${gateData.chat_id}\``,
  `• *Escalation Reason:* \`${gateData.escalation_reason}\``,
  `• *Telemetry:* Top-1 Sim = \`${gateData.top1_similarity}\` | LLM Conf = \`${gateData.llm_confidence}\` | Composite = \`${gateData.composite_confidence}\``,
  '',
  '💬 *Full Conversation History (Last Turns):*',
  transcriptText
].join('\n');

return [{
  json: {
    ...gateData,
    human_ticket_text: alertMessage
  }
}];
